facts=[dict(id='F_match',meaning='For a voter ID in a particular commitment tracker, matchIndexes records the greatest reported matching stored prefix index.',identity={'tracker':'leader epoch commitment object','server':'ServerID'},validity_context='Only IDs currently present in tracker voter map count; configuration replacement retains values by ID and a new leader creates a new tracker.',representation=['commitment.matchIndexes'],durability='Volatile aggregation over log storage acknowledgments.',recovery='Rebuilt from zero in each leader epoch; local persistence and new replies establish matches.',source_ids=['s_commitment','s_leader','s_dispatch','s_match'],unknowns=[]),dict(id='F_commit',meaning='The leader commitment object has found a voter quorum whose matching prefix reaches an index at or beyond this epoch first entry.',identity={'tracker':'leader epoch commitment object','index':'commitment.commitIndex'},validity_context='The tracker uses its current voter map and only increases commitIndex after the current-term startIndex threshold.',representation=['commitment.commitIndex','commitCh','Raft commitIndex'],durability='Commit index is volatile; log and snapshot history are durable through injected stores.',recovery='A new leader re-establishes commitment through a current-term entry; follower learns commit position from append traffic.',source_ids=['s_commitment','s_commit_consume','s_append'],unknowns=[]),dict(id='F_verify_tally',meaning='A verifyFuture contains a self vote plus true notifications from registered replication workers, and notifies the leader when its tally reaches its captured threshold or any worker reports false.',identity={'operation':'verifyFuture pointer'},validity_context='Registration occurs during one leader epoch; threshold uses latest voter count but registrations cover the replication-worker set.',representation=['verifyFuture.votes','verifyFuture.quorumSize','verifyFuture.notifyCh'],durability='Volatile; not persisted.',recovery='No recovery of a verify operation; leader exit fails pending registered futures.',source_ids=['s_verify','s_notify','s_verify_count','s_leader'],unknowns=[])]
