mapdoc=dict(version=1,target_profile=dict(system_boundary='Captured HashiCorp Raft Go module: Raft owns protocol loops, replication, membership and snapshot orchestration. Applications inject FSM and stores; in-repository transports and in-memory stores are implementations, not externalized unread responsibilities.',protocol_contexts=['Server identity, current term, leader epoch, latest/committed configuration and log/snapshot indexes'],external_interfaces=['Apply/Barrier/VerifyLeader and membership APIs','Transport RPCs','FSM and optional BatchingFSM/ConfigurationStore','LogStore, StableStore, SnapshotStore'],source_ids=['s_init','s_transport','s_fsm_contract','s_stable','s_config'],unknowns=['Detailed failure contracts and implementations of injected stores remain to be examined.']),activities=activities,behaviors=bs,facts=facts,surfaces=[dict(entry_point='Raft.installSnapshot',disposition='mapped',behavior_ids=['B_recovery'],reason='Does a same-term delayed snapshot restore an older application state after a more advanced prefix has completed? Sender ordering and legal history remain to be established.',source_ids=['s_install','s_send_snapshot'],high_consequence=True),dict(entry_point='Raft.processHeartbeat',disposition='mapped',behavior_ids=['B_append_receive'],reason='NewRaft requires concurrent heartbeat safety while handler comments require main-thread execution. Determine protection for overlapping term persistence and role transitions.',source_ids=['s_init','s_append','s_net_heartbeat'],high_consequence=True),dict(entry_point='Raft.persistVote',disposition='mapped',behavior_ids=['B_election'],reason='Determine crash/error behavior between separate term and candidate stable-store writes and whether an old candidate can be reinterpreted in a new term.',source_ids=['s_persist','s_vote','s_stable'],high_consequence=True)],core_overview=dict(status='usable',formation=path('Leader admits commands, assigns current term/index and persists before local match. Peer workers replicate ordered prefixes, backtrack conflicts, fall back to snapshots and report successful stored prefixes. A voter-only tracker selects the majority prefix, gated by the first current-term entry. The leader copies commitment, advances membership and sends committed logs to the FSM queue; followers learn commit position from periodic append traffic. FSM callbacks complete command futures; queueing is not completion.',['B_dispatch','B_replication','B_commit','B_append_receive','B_apply'],['F_match','F_commit'],['s_dispatch','s_replicate','s_commitment','s_commit_consume','s_append','s_process','s_fsm']),context=path('Follower contact timeout allows configured voters to campaign. Optional pre-vote precedes durable term increment and one request per voter. Receivers constrain votes using known leader, membership, term, durable vote and log freshness. A campaign-specific response channel prevents replies from prior campaigns being tallied in a new one. Majority victory creates fresh leader state and an initial noop. Higher-term RPC/reply, lease loss and committed local removal can end leadership. Pending leader operations fail on exit while previously committed FSM work retains its separate completion path. Startup reconstructs term, snapshot and later configuration history.',['B_election','B_leader_epoch','B_recovery','B_configuration'],[],['s_election','s_elect_send','s_vote','s_leader','s_lease','s_init','s_install']),connection=path('Election log freshness and stored votes constrain who acquires authority over prior history. Each leader creates a new commitment object; late replication workers retain their old object and cannot directly populate the new tracker. New-term noop commitment establishes the prefix before configuration changes are admitted. Membership reinterprets eligible match support by voter ID, while all members retain replication workers. Log matching/truncation and snapshot reconstruction handle old work; committed commands continue through a distinct FSM queue. Verification is another authority consumer: its voter-sized threshold is currently fed by the broader replication-worker set, which is the first focused question.',['B_election','B_leader_epoch','B_configuration','B_replication','B_commit','B_recovery','B_verify_register','B_verify_ack','B_verify_result'],['F_match','F_commit','F_verify_tally'],['s_leader','s_commitment','s_config_gate','s_config','s_append','s_install','s_verify','s_notify','s_verify_count']),open_details=['Verification eligibility and legal failure history are the selected discriminator.','Same-term snapshot age, concurrent heartbeat authority updates and partial vote persistence remain sourced surfaces.','Leadership-transfer edge cases, protocol-version compatibility and store error semantics are not exhaustively traced.'],core_gaps=[],rationale='Representative formation and context paths, their voter/log/epoch connection and supporting recovery/application mechanisms have been read. This is a usable partial understanding, not a coverage claim.'))
json.dump(mapdoc,open('map.json','w'),indent=2)
question=dict(question='Can successful VerifyLeader completion be established by nonvoter replication acknowledgments when the current leader lacks responses from a voter quorum, and what authority responsibility applies to that result?',importance='Incorrect leadership confirmation can let an application return stale FSM data after another voter quorum has elected a leader; the current source discrepancy alone does not establish that complete history or endpoint.',source_ids=['s_verify_api','s_verify','s_notify','s_verify_count','s_leader','s_lease','s_suffrage','s_commit_consume'],participants=['Current leader','Voting peers','Nonvoting replication peers','VerifyLeader caller'],objects=['verifyFuture','followerReplication.notify','latest configuration'],contexts=['Stable mixed voter/nonvoter membership in one leader epoch','Replies during a selected communication partition before local stepdown'],event_paths=['VerifyLeader -> verifyCh -> verifyLeader -> each repl.notify -> heartbeat/append reply -> notifyAll -> vote -> verifyCh -> success'],activity_classes=['A2'],behavior_ids=['B_verify_ack','B_verify_result'],fact_ids=['F_verify_tally'],supporting_behavior_ids={'B_verify_register':'Sets voter-count threshold but registers all workers.','B_configuration':'Constructs mixed membership and broader replication-worker set.','B_leader_epoch':'Acquires authority and supplies competing lease/stepdown protection.','B_client':'Public VerifyLeader contract motivates use for avoiding stale reads.'},obligation_relation_kind='establishment',counterevidence=['Commitment uses only voter match indexes and lease checks explicitly count only voters.','Any negative registered response can cause failure; leader exit fails pending verification.','Lease timeout may end the relevant window; nonvoter presence alone does not show stale data or an elected successor.'],unknowns=['Clarify the exact applicable authority guarantee of VerifyLeader and whether independently grounded eligibility suffices for a scoped obligation.','Construct legal membership/leadership history and controlled transport schedule that observes which peers supply positive replies while preserving lease and negative-response paths.'],priority=3,trigger_rationale='The producer set differs from both the voter-derived threshold and explicit voter filters in commitment/lease code. Trace and a smaller isolated check can distinguish an accounting discrepancy; a full stale-read claim additionally needs a correlated successor election and endpoint. Snapshot-age and vote-persistence leads require more fault/history investigation, so verification has the most concrete current discriminator.',disposition='concrete_suspicion',preferred_check='controlled_schedule')
